<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />
    <div class="optimization-option">
      <div class="optimization-option__box">
        <div class="optimization-option__item">
          <AdsDropdown
            v-if="selectVisibility"
            placeholder="Все"
            :defaultValue="selectHeaderOption"
            @updateSort="chekedSort"
            :options="options"
          />
          <CustomSerch
            v-model="searchQuery"
            placeholder="Название, идентификатор"
            @onFocus="selectVisibility = false"
            @OutFocus="visibilityChecker"
            @clickIcon="serchAction"
          />
        </div>

        <CustomTableOption
          v-model="selectRoleHeader"
          @update:model-value="selectOption"
          :btnClass="'btn--primary'"
          :options="optionsHeader"
        />
      </div>
    </div>
    <div class="optimization-table__box">
      <template v-if="!isLoading && items.length === 0">
        <div class="empty-placeholder">
          <p>Ничего не найдено</p>
          <span>
            Вы можете добавить новый
            <span class="empty-placeholder__link" @click="goToCreate('region')"
              >регион</span
            >
            или
            <span class="empty-placeholder__link" @click="goToCreate('city')"
              >город</span
            >
          </span>
        </div>
      </template>

      <CustomTableNew
        v-else
        :itemRows="items"
        :immersed="isNested"
        :headerRows="headerRow"
        @slot-clicked="handleButtonClick"
        :current-page="pagination.currentPage"
        :per-page="pagination.perPage"
        :total="pagination.total"
        @update:currentPage="(val) => handlePageChange(val)"
        @update:perPage="(val) => handlePerPageChange(val)"
      >
        <template #slot-end="{ item, emitEvent }">
          <div class="table-box__item-box--slot">
            <ButtonUI
              v-if="item.id.select === 'reg'"
              svg="addad-t"
              :buttonClass="'btn--third'"
              @click="emitEvent('generation', item)"
            />
            <ButtonUI
              svg="pencil-svg"
              :buttonClass="'btn--third'"
              @click="emitEvent('redact', item)"
            />
          </div>
        </template>
      </CustomTableNew>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue';
import { getCitiesRegions } from '@/services/apiClient';
import {
  transformSearchResults,
  formatCityData,
  formatRegionData,
  formatOnlyRegionData,
} from '@/services/tableUtils';

import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import AdsDropdown from '@/components/AdsDropdown';
import CustomTableNew from '@/components/UI/CustomTableNew.vue';
import CustomTableOption from '@/components/UI/CustomTableOption.vue';
import CustomSerch from '@/components/UI/CustomSerch.vue';
import ButtonUI from '@/components/UI/ButtonUI';

import { useQueryParams } from '@/composables/useQueryParams';
import { useRouter } from 'vue-router';

const title = ref('Регионы и города');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');

const goToCreate = (type) => {
  router.push({ name: 'CreateLocation', params: { type } });
};

const pagination = ref({ currentPage: 1, perPage: 3, total: 100 });
const filterType = ref('all');
const searchQuery = ref('');
const isLoading = ref(true);

const selectVisibility = ref(true);
const router = useRouter();

const { updateQueryParams, loadQueryParamsFromRoute } = useQueryParams();

const isNested = computed(() => {
  return (
    Array.isArray(items.value) &&
    items.value.length > 0 &&
    items.value[0].itemRows !== undefined &&
    items.value[0].option !== undefined
  );
});

const handlePageChange = (newPage) => {
  pagination.value.currentPage = newPage;
  getTableItem();
  updateQueryParams();
};

const handlePerPageChange = (val) => {
  pagination.value.perPage = val;
  pagination.value.currentPage = 1;
  getTableItem();
  updateQueryParams();
};

const optionsHeader = [
  {
    name: 'Добавить регион',
    code: 'defol',
    error: false,
    success: false,
    svg: 'addad-option',
    ValidateType: 'select',
  },
  {
    name: 'Добавить город',
    code: 'defol',
    error: false,
    success: false,
    svg: 'addad-reg',
    ValidateType: 'select',
  },
  {
    name: 'Читать лог',
    code: 'readLog',
    error: false,
    success: false,
    svg: 'log-option',
    ValidateType: 'select',
  },
];
const options = ref([
  { label: 'Все', value: 'all' },
  { label: 'Города', value: 'cities' },
  { label: 'Регионы', value: 'reg' },
]);
const selectHeaderOption = ref('Города');
const items = ref(null);

const headerRow = [
  {
    name: 'Место',
    width: '20%',
    helper: false,
  },
  {
    name: 'Идетификатор',
    helper: {
      title: 'Идентификатор',
      text: 'Используется для идентификации региона или населенного пункта в системе',
    },
    width: '14%',
  },
  {
    name: 'Пред. падеж',
    helper: {
      title: 'Предложный падеж',
      text: 'Склонение названия региона или населенного пункта для корректного формирования заголовков на страницах',
    },
    width: '15%',
  },
  {
    name: 'Транслит',
    helper: {
      title: 'Транслит',
      text: 'Названия региона или населенного пункта в латинской транскрипции для использования в URL',
    },
    width: '14%',
  },
  {
    name: 'ЧПУ',
    helper: {
      title: 'ЧПУ',
      text: 'Человекопонятный URL (адрес) ресурса в интернете. Так называют ссылку на веб-страницу, которая позволяет пользователю понять, о чем она.',
    },
    width: '50px',
  },
  {
    name: 'Р.центр',
    helper: {
      title: 'Региональный центр',
      text: 'Основной город данного региона, считающийся административным центром. Используется по умолчанию для локации пользователей, данные о местонахождении которых не удалось получить.',
    },
    width: '12%',
  },
  {
    name: '',
    helper: false,
    width: '60px',
  },
];

const selectOption = (value) => {
  if (value.name === 'Добавить регион') {
    router.push({ name: 'CreateLocation', params: { type: 'region' } });
  }

  if (value.name === 'Добавить город') {
    router.push({ name: 'CreateLocation', params: { type: 'city' } });
  }

  if (value.name === 'Читать лог') {
    router.push('/seo/location/log');
  }
};

const serchAction = (type) => {
  pagination.value.currentPage = 1;

  if (type === 'serch' && searchQuery.value.trim()) {
    filterType.value = 'all';
    pagination.value.perPage = 10000;
  }

  if (type === 'cler') {
    searchQuery.value = '';
    filterType.value = 'all';
    pagination.value.perPage = 3;
  }

  getTableItem();
};

const visibilityChecker = () => {
  if (searchQuery.value.length === 0) {
    selectVisibility.value = true;
  } else {
    selectVisibility.value = false;
  }
};

const chekedSort = (option) => {
  filterType.value = option;
  pagination.value.currentPage = 1;
  if (option === 'cities' || option === 'reg') {
    pagination.value.perPage = 20;
  } else {
    pagination.value.perPage = 3;
  }
  getTableItem();
  updateQueryParams();
};

const typeMap = {
  city: 'city',
  reg: 'region',
};

const handleButtonClick = (name, item) => {
  const locationId = item.id?.value;
  const type = item.id?.select;

  if (!locationId || !type) {
    console.warn('Не хватает данных для перехода');
    return;
  }

  if (name === 'redact') {
    router.push({
      name: 'EditLocation',
      params: { type: typeMap[type], id: locationId },
    });
  }

  if (name === 'generation') {
    router.push({ name: 'CreateLocation', params: { type: 'city' } });
  }
};

const getTableItem = async () => {
  try {
    isLoading.value = true;
    const params = {
      order_by: 'asc',
      search_title_id: searchQuery.value || undefined,
      count: pagination.value.perPage,
      page: pagination.value.currentPage,
    };

    if (filterType.value === 'cities') {
      params.is_only_city = 1;
    } else if (filterType.value === 'reg') {
      params.is_only_region = 1;
    }

    const response = await getCitiesRegions(params);

    if (Array.isArray(response.data)) {
      if (searchQuery.value) {
        items.value = transformSearchResults(response.data);
      } else if (filterType.value === 'cities') {
        items.value = formatCityData(response.data);
      } else if (filterType.value === 'reg') {
        items.value = formatOnlyRegionData(response.data);
      } else {
        items.value = formatRegionData(response.data);
      }
    }

    if (response.total_count) {
      pagination.value.total = response.total_count;
    }
  } catch (e) {
    console.error('Ошибка при загрузке данных:', e);
  } finally {
    isLoading.value = false;
  }
};

onMounted(() => {
  loadQueryParamsFromRoute();
  getTableItem();
});
</script>

<style scoped lang="scss">
.optimization {
  margin: 16px 24px 16px 16px;
  width: calc(100% - 32px);
  display: flex;
  flex-direction: column;
  height: calc(100vh - 40px);

  @media (max-width: 1024px) {
    justify-content: space-between;
    width: calc(100% - 40px);
    height: calc(100vh - 40px);
  }

  &-table__box {
    height: calc(100vh - 200px);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  &-option {
    display: flex;
    justify-content: space-around;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 24px 0;
    padding: 12px 24px;

    &__box {
      display: flex;
      justify-content: space-between;
      width: 100%;

      .dropdown-2 {
        max-width: 232px;
      }

      .ui-input-serch {
        width: 100%;
      }

      @media (max-width: 1024px) {
        display: flex;
        flex-direction: column;

        .dropdown-2 {
          max-width: 100%;
        }

        .ui-input-serch {
          max-width: 100%;
        }
      }
    }

    &__item {
      display: flex;
      align-items: center;
      gap: 18px;
      width: 65%;
      margin-bottom: 0;

      @media (max-width: 1024px) {
        display: flex;
        flex-direction: column;
        align-items: inherit;
        margin-bottom: 16px;
        width: 100%;
      }
    }
  }
}

.table-box__item-box--slot {
  width: 100%;
  display: flex;
  justify-content: flex-end;
  gap: 12px;

  .btn {
    padding: 2px 2px;
  }
}

.empty-placeholder {
  padding: 24px;

  p {
    font-size: 16px;
    color: #323232;
    font-weight: 700;
    margin-bottom: 8px;
  }

  span {
    font-size: 14px;
    color: #323232;

    .empty-placeholder__link {
      color: #3366ff;
      cursor: pointer;
      text-decoration: underline;

      &:hover {
        text-decoration: none;
      }
    }
  }
}
</style>
